//! Dispatch wrapper for tile grid canvas messages and view.
//!
//! This module exists so the `define_update_dispatch!` and
//! `define_view_dispatch!` macros can route `EditorMessage::TileGridCanvas`
//! and `EditorType::TileGridEditor` to the canvas-based handler/view
//! without colliding with the standard spreadsheet functions generated by
//! `define_standard_editor!` for `StandardEditorMessage<TileGrid>`.

use crate::editors::tile_grid::{self, TileGridCanvasMessage, TileGridViewState};
use crate::message::Message;
use iced::Task;

pub fn handle(msg: TileGridCanvasMessage, app: &mut crate::app::App) -> Task<Message> {
    tile_grid::handle_canvas_message(msg, app)
}

/// Render the tile grid canvas view. Reads the loaded grid from
/// `tile_grid_editor` and the pan/zoom state from `tile_grid_view`.
pub fn view(app: &crate::app::App) -> iced::Element<'_, Message> {
    let view: &TileGridViewState = &app.state.editors.tile_grid_view;
    if let Some(catalog) = app.state.editors.tile_grid_editor.state.catalog.as_ref()
        && let Some(grid) = catalog.first()
    {
        return tile_grid::view::view_canvas(grid, view);
    }
    // Fallback: show a "no grid loaded" message
    use iced::widget::{center, text};
    center(text("No tile grid loaded. Open a .dat file from the file tree.").size(18)).into()
}
